<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Compare Marginalia plans: Starter, Pro, and Team. Find the right home for your notes, from your first notebook to shared team workspaces.">
  <meta name="theme-color" content="#f8f7f3">
  <title>Pricing — Marginalia</title>
  <style>
    :root {
      --paper: #f8f7f3;
      --surface: #fffefa;
      --ink: #292c28;
      --muted: #62655e;
      --line: #ddded6;
      --accent: #9b3e32;
      --accent-hover: #7d3027;
      --accent-soft: #f4e8e3;
      --unavailable: #72756e;
      --button-border: #85877e;
      --serif: '"'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
      --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
      --text-sm: 14px;
      --text-base: 16px;
      --text-lg: 18px;
      --text-title: 32px;
      --text-price: 48px;
      --space-1: 4px;
      --space-2: 8px;
      --space-3: 12px;
      --space-4: 16px;
      --space-6: 24px;
      --space-8: 32px;
      --space-12: 48px;
      --space-16: 64px;
      --space-24: 96px;
      --radius: 6px;
      --transition: 150ms ease-out;
    }
    * { box-sizing: border-box; }
    body { margin: 0; background: var(--paper); color: var(--ink); font: var(--text-base)/1.5 var(--sans); -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }
    button, a, summary { -webkit-tap-highlight-color: transparent; }
    :focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
    h1, h2, h3, p { margin: 0; }
    h1, h2 { text-wrap: balance; }
    svg { display: block; flex-shrink: 0; }
    .container { width: min(1120px, calc(100% - var(--space-12) * 2)); margin-inline: auto; }
    .skip-link { position: absolute; top: -80px; left: var(--space-4); z-index: 2; padding: var(--space-3) var(--space-4); background: var(--surface); }
    .skip-link:focus { top: var(--space-4); }
    .header { border-bottom: 1px solid var(--line); }
    .nav { display: flex; align-items: center; justify-content: space-between; min-height: 88px; gap: var(--space-8); }
    .logo { display: inline-flex; align-items: center; gap: var(--space-3); font: 600 26px/1 var(--serif); letter-spacing: -1px; }
    .logo-mark { color: var(--accent); width: 25px; height: 32px; }
    .nav-links { display: flex; align-items: center; gap: var(--space-8); font-size: var(--text-sm); }
    .nav-links > a { display: inline-flex; align-items: center; min-height: 44px; color: var(--muted); transition: color var(--transition); }
    .nav-links > a:hover { color: var(--accent); }
    .nav-links > [aria-current] { color: var(--ink); text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: 8px; }
    .nav-links .signup { padding: var(--space-3) var(--space-4); border: 1px solid var(--button-border); border-radius: var(--radius); color: var(--ink); }
    .nav-links .signup:hover { background: var(--accent-soft); border-color: var(--accent); }
    .hero { text-align: center; padding-top: var(--space-16); padding-bottom: var(--space-12); }
    .hero h1 { font: 400 clamp(40px, 4.5vw, 60px)/1.12 var(--serif); letter-spacing: -2px; }
    .hero p { max-width: 540px; margin: var(--space-6) auto 0; color: var(--muted); font-size: var(--text-lg); }
    .billing { display: flex; justify-content: center; margin-top: var(--space-8); }
    .toggle { display: inline-flex; padding: var(--space-1); gap: var(--space-1); border: 1px solid var(--line); border-radius: var(--radius); }
    .toggle button { min-height: 44px; padding: var(--space-2) var(--space-4); border: 0; border-radius: 3px; background: transparent; color: var(--muted); cursor: pointer; font-size: var(--text-sm); transition: background var(--transition), color var(--transition); }
    .toggle button:hover { color: var(--ink); background: var(--surface); }
    .toggle [aria-pressed=\"true\"] { background: var(--ink); color: var(--surface); }
    .toggle [aria-pressed=\"true\"]:hover { background: var(--ink); color: var(--surface); }
    .saving { margin-left: var(--space-2); color: var(--accent); font-size: 12px; font-weight: 600; }
    [aria-pressed=\"true\"] .saving { color: var(--surface); }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); }
    .plan { position: relative; padding: var(--space-8); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); display: flex; flex-direction: column; }
    .plan.popular { border-color: var(--accent); }
    .plan.popular::before { content: ''; position: absolute; top: -1px; left: -1px; right: -1px; height: 4px; background: var(--accent); border-radius: var(--radius) var(--radius) 0 0; }
    .plan-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); }
    .plan h2 { font: 400 var(--text-title)/1.2 var(--serif); letter-spacing: -0.5px; }
    .badge { padding: var(--space-1) var(--space-2); background: var(--accent-soft); color: var(--accent); font-size: 12px; font-weight: 600; border-radius: 3px; white-space: nowrap; }
    .desc { margin-top: var(--space-2); color: var(--muted); font-size: var(--text-sm); }
    .price { display: flex; align-items: baseline; gap: var(--space-2); margin-top: var(--space-8); font-variant-numeric: tabular-nums; }
    .amount { font-size: var(--text-price); line-height: 1.2; font-weight: 500; letter-spacing: -2px; }
    .price small { color: var(--muted); font-size: var(--text-sm); white-space: nowrap; }
    .billing-note { margin-top: var(--space-2); min-height: 21px; font-size: var(--text-sm); color: var(--muted); }
    .btn { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); min-height: 48px; margin-top: var(--space-6); padding: var(--space-3) var(--space-4); border: 1px solid var(--button-border); border-radius: var(--radius); font-size: var(--text-sm); font-weight: 600; transition: background var(--transition), border-color var(--transition); }
    .btn:hover { background: var(--paper); border-color: var(--ink); }
    .btn:active { background: var(--accent-soft); }
    .btn .arrow { font-size: var(--text-lg); line-height: 1; font-weight: 400; }
    .popular .btn { background: var(--accent); color: var(--surface); border-color: var(--accent); }
    .popular .btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
    .popular .btn:active { background: var(--ink); border-color: var(--ink); }
    .plan ul { list-style: none; margin: var(--space-8) 0 0; padding: var(--space-6) 0 0; border-top: 1px solid var(--line); display: grid; gap: var(--space-4); }
    .plan li { display: flex; align-items: baseline; gap: var(--space-3); font-size: var(--text-sm); }
    .plan li::before { content: '✓'; color: var(--accent); font-size: var(--text-sm); flex: 0 0 12px; }
    .plan li.unavailable { color: var(--unavailable); }
    .plan li.unavailable::before { content: '−'; color: var(--unavailable); }
    .sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
    .features { margin-top: var(--space-16); padding-block: var(--space-8); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
    .feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-12); }
    .feature { display: flex; align-items: flex-start; gap: var(--space-4); }
    .feature svg { width: 22px; height: 22px; margin-top: var(--space-1); color: var(--muted); }
    .feature h3 { font-size: var(--text-sm); font-weight: 600; }
    .feature p { color: var(--muted); font-size: var(--text-sm); margin-top: var(--space-1); max-width: 28ch; }
    .faq { display: grid; grid-template-columns: 1fr 1.7fr; gap: var(--space-16); padding-block: var(--space-24); }
    .faq h2 { font: 400 var(--text-title)/1.2 var(--serif); letter-spacing: -0.5px; max-width: 12ch; }
    .question { border-bottom: 1px solid var(--line); }
    .question:first-child { border-top: 1px solid var(--line); }
    .question summary { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); min-height: 64px; padding-block: var(--space-4); list-style: none; font-weight: 500; cursor: pointer; }
    .question summary::-webkit-details-marker { display: none; }
    .question summary::after { content: '+'; color: var(--accent); font-size: 24px; font-weight: 400; }
    .question[open] summary::after { content: '−'; }
    .question summary:hover { color: var(--accent); }
    .question p { padding: 0 var(--space-8) var(--space-6) 0; color: var(--muted); font-size: var(--text-sm); max-width: 60ch; }
    .footer { border-top: 1px solid var(--line); }
    .footer-inner { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); min-height: 96px; }
    .footer .logo { font-size: 22px; }
    .footer p { font-size: 12px; color: var(--muted); }
    @media (max-width: 1050px) {
      .container { width: calc(100% - var(--space-8) * 2); }
      .plans { gap: var(--space-4); }
      .plan { padding: var(--space-6); }
      .plan-heading { flex-wrap: wrap; align-content: start; min-height: 68px; }
      .price { flex-wrap: wrap; gap: 0 var(--space-2); min-height: 88px; align-content: start; }
      .price small { width: 100%; }
      .feature-grid { gap: var(--space-6); }
    }
    @media (max-width: 700px) {
      .container { width: calc(100% - var(--space-6) * 2); }
      .nav { min-height: 80px; gap: var(--space-4); flex-wrap: wrap; padding-block: var(--space-4); }
      .nav-links { width: 100%; gap: var(--space-6); flex-wrap: wrap; }
      .nav-links .signup { margin-left: auto; }
      .nav-links .blog-link { display: none; }
      .hero { padding-top: var(--space-12); padding-bottom: var(--space-8); }
      .hero h1 { letter-spacing: -1px; }
      .hero p { font-size: var(--text-base); max-width: 34ch; margin-top: var(--space-4); }
      .plans { grid-template-columns: 1fr; gap: var(--space-6); }
      .plan { padding: var(--space-8); }
      .plan-heading { min-height: 0; }
      .price { min-height: 0; margin-top: var(--space-6); }
      .price small { width: auto; }
      .feature-grid { grid-template-columns: 1fr; gap: var(--space-8); }
      .feature p { max-width: none; }
      .faq { grid-template-columns: 1fr; gap: var(--space-8); padding-block: var(--space-16); }
      .faq h2 { max-width: none; }
      .footer-inner { flex-wrap: wrap; padding-block: var(--space-6); gap: var(--space-4); }
    }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none "'!important; } }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="header">
    <nav class="nav container" aria-label="Main navigation">
      <a class="logo" href="#" aria-label="Marginalia home">
        <svg class="logo-mark" viewBox="0 0 25 32" fill="none" aria-hidden="true"><path d="M5 3h17v26H5M9 3v26M2 9h12M2 15h12M2 21h12" stroke="currentColor" stroke-width="1.5"/></svg>
        Marginalia
      </a>
      <div class="nav-links">
        <a href="#features">Features</a>
        <a href="#pricing" aria-current="page">Pricing</a>
        <a class="blog-link" href="#">Blog</a>
        <a href="#">Login</a>
        <a class="signup" href="#">Sign up free <span aria-hidden="true">&nbsp;↗</span></a>
      </div>
    </nav>
  </header>
  <main id="main" class="container">
    <section class="hero" id="pricing" aria-labelledby="pricing-title">
      <h1 id="pricing-title">A plan for every notebook.</h1>
      <p>Start with 100 notes for free. Find more room for your ideas with Pro, or bring everyone together with Team.</p>
      <div class="billing">
        <div class="toggle" role="group" aria-label="Billing period">
          <button type="button" aria-pressed="true" data-billing="monthly">Monthly</button>
          <button type="button" aria-pressed="false" data-billing="yearly">Yearly <span class="saving">Save 20%</span></button>
        </div>
      </div>
    </section>
    <section class="plans" aria-label="Compare plans">
      <article class="plan" aria-labelledby="starter-title">
        <div class="plan-heading"><h2 id="starter-title">Starter</h2></div>
        <p class="desc">For your first collection of ideas.</p>
        <div class="price"><span class="amount">$0</span><small>/ month</small></div>
        <p class="billing-note">Free</p>
        <a class="btn" href="#" aria-label="Get started with Starter">Get started free <span class="arrow" aria-hidden="true">↗</span></a>
        <ul>
          <li>Up to 100 notes</li>
          <li>2 devices</li>
          <li>Basic search</li>
          <li class="unavailable"><span><span class="sr-only">Not included: </span>Offline access</span></li>
          <li class="unavailable"><span><span class="sr-only">Not included: </span>Shared notebooks</span></li>
        </ul>
      </article>
      <article class="plan popular" aria-labelledby="pro-title">
        <div class="plan-heading"><h2 id="pro-title">Pro</h2><span class="badge">Most popular</span></div>
        <p class="desc">For a growing world of notes.</p>
        <div class="price"><span class="amount" data-monthly="8" data-yearly="6.40">$8</span><small>/ month</small></div>
        <p class="billing-note" data-monthly-note="Billed monthly" data-yearly-note="$76.80 billed yearly">Billed monthly</p>
        <a class="btn" href="#" aria-label="Start your Pro free trial">Start Pro trial <span class="arrow" aria-hidden="true">↗</span></a>
        <ul>
          <li>Unlimited notes</li>
          <li>Unlimited devices</li>
          <li>Full-text search inside PDFs</li>
          <li>Offline access</li>
          <li class="unavailable"><span><span class="sr-only">Not included: </span>Shared notebooks</span></li>
        </ul>
      </article>
      <article class="plan" aria-labelledby="team-title">
        <div class="plan-heading"><h2 id="team-title">Team</h2></div>
        <p class="desc">For ideas that belong together.</p>
        <div class="price"><span class="amount" data-monthly="14" data-yearly="11.20">$14</span><small>/ user / month</small></div>
        <p class="billing-note" data-monthly-note="Billed monthly" data-yearly-note="$134.40 per user, billed yearly">Billed monthly</p>
        <a class="btn" href="#" aria-label="Get started with Team">Get started with Team <span class="arrow" aria-hidden="true">↗</span></a>
        <ul>
          <li>Everything in Pro</li>
          <li>Shared notebooks</li>
          <li>Admin controls</li>
          <li>Priority support</li>
          <li>SSO</li>
        </ul>
      </article>
    </section>
    <p class="sr-only" id="billing-announcement" role="status" aria-live="polite"></p>
    <section class="features" id="features" aria-label="Why choose Marginalia">
      <div class="feature-grid">
        <div class="feature">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5M8 10.5h5m-2.5-2.5v5"/></svg>
          <div><h3>Find it fast</h3><p>Quick search for the thought you’re looking for.</p></div>
        </div>
        <div class="feature">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></svg>
          <div><h3>Keep it secure</h3><p>Your notes stay safe and encrypted.</p></div>
        </div>
        <div class="feature">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M20 9a8 8 0 0 0-14-3L3 9m0-5v5h5M4 15a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/></svg>
          <div><h3>Pick up anywhere</h3><p>Your notes, in sync across your devices.</p></div>
        </div>
      </div>
    </section>
    <section class="faq" aria-labelledby="faq-title">
      <h2 id="faq-title">A few things you might be wondering.</h2>
      <div>
        <details class="question" open>
          <summary>Can I cancel anytime?</summary>
          <p>Yes. You can cancel your subscription at any time, no questions asked.</p>
        </details>
        <details class="question">
          <summary>Is there a free trial for Pro?</summary>
          <p>Yes. Pro comes with a 14-day free trial. No credit card required.</p>
        </details>
        <details class="question">
          <summary>Do you offer student discounts?</summary>
          <p>Students get 50% off Pro with a valid school email.</p>
        </details>
      </div>
    </section>
  </main>
  <footer class="footer">
    <div class="container footer-inner">
      <a href="#" class="logo">Marginalia</a>
      <p>© 2026 Marginalia Inc. All rights reserved.</p>
    </div>
  </footer>
  <script>
    const billingButtons = document.querySelectorAll('"'[data-billing]');
    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const period = button.dataset.billing;
        billingButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
        document.querySelectorAll('[data-monthly]').forEach(price => {
          price.textContent = '"'$'"' + price.dataset[period];
        });
        document.querySelectorAll('[data-monthly-note]').forEach(note => {
          note.textContent = note.dataset[period + 'Note'];
        });
        document.querySelector('#billing-announcement').textContent = period === 'yearly'
          ? 'Yearly billing selected. Pro is "'$6.40 per month, billed $76.80 yearly. Team is $11.20 per user per month, billed $134.40 yearly.'"'
          : 'Monthly billing selected. Pro is "'$8 per month. Team is $14 per user per month.'"';
      });
    });
  </script>
</body>
</html>
EOF
